-- Logistics Delivery — analysis queries (SQLite, run against outputs/logistics.db)
-- Schema: fact_shipments + dim_carrier, dim_destination_zone
-- NOTE: dataset is synthetic sample data generated by generate_data.py.

-- 1. Overall delivery performance (on_time is set only for Delivered rows)
SELECT COUNT(*) AS shipments,
       SUM(status = 'Delivered') AS delivered,
       ROUND(100.0 * AVG(on_time), 2) AS on_time_pct,
       ROUND(AVG(delay_days), 2) AS avg_delay_days,
       ROUND(SUM(shipping_cost), 2) AS total_shipping_cost
FROM fact_shipments;

-- 2. Carrier scorecard: on-time %, average delay, cost per kg
SELECT c.carrier, COUNT(*) AS shipments,
       ROUND(100.0 * AVG(f.on_time), 1) AS on_time_pct,
       ROUND(AVG(f.delay_days), 2) AS avg_delay_days,
       ROUND(AVG(f.cost_per_kg), 2) AS cost_per_kg
FROM fact_shipments f JOIN dim_carrier c USING (carrier_key)
GROUP BY c.carrier ORDER BY on_time_pct DESC;

-- 3. Destination-zone performance
SELECT z.zone, COUNT(*) AS shipments,
       ROUND(100.0 * AVG(f.on_time), 1) AS on_time_pct,
       ROUND(AVG(f.delay_days), 2) AS avg_delay_days
FROM fact_shipments f JOIN dim_destination_zone z USING (zone_key)
GROUP BY z.zone ORDER BY on_time_pct;

-- 4. Late-delivery cost impact
SELECT COUNT(*) AS late_shipments,
       ROUND(SUM(shipping_cost), 2) AS cost_of_late_shipments,
       ROUND(AVG(shipping_cost), 2) AS avg_late_shipment_cost,
       ROUND(AVG(delay_days), 2) AS avg_late_delay_days
FROM fact_shipments WHERE on_time = 0;

-- 5. On-time trend by ship month
SELECT substr(ship_date, 1, 7) AS ship_month,
       ROUND(100.0 * AVG(on_time), 1) AS on_time_pct,
       COUNT(*) AS shipments
FROM fact_shipments WHERE status = 'Delivered'
GROUP BY ship_month ORDER BY ship_month;
